---AddSuitDataPartListByEquipId
---根据 装备数据库id 添加套装位置数据
---@param playerEquipId number 装备数据库id
function CardProgressionBaseEquipmentListNode:AddSuitDataPartListByEquipId(playerEquipId)
    local temp = checkNumber(playerEquipId)
    local equipIdList = self:GetEquipIdList()
    for i, v in pairs(equipIdList) do
        if checkNumber(v) == temp then
            return
        end
    end

    ---@type EquipDojo
    local equipDojo = self.equipComp:GetEquipById(playerEquipId)
    ---@type EquipVo
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local suitId = checkInt(equipVo.suitId)
    if suitId == self.curSelectSuitId and self.curSelectSuitId > 0 then
        local part = checkNumber(equipVo.part)
        local suitDataPartList = self.suitDataPartList
        suitDataPartList[part] = suitDataPartList[part] or {}

        if self:CheckIsCanInsert(suitDataPartList[part], checkNumber(playerEquipId), equipDojo, equipVo, true) then
            table.insert(suitDataPartList[part], self:CreateEquipData(equipDojo, equipDojo.equipmentId, equipVo.rare, part, suitId))
        end
    end
end

---RemoveSuitDataPartListData
---移除套装位置列表数据
---@param id number 数据id
---@param part number 套装散件位置
function CardProgressionBaseEquipmentListNode:RemoveSuitDataPartListData(id, part)
    local suitDataPartList = self.suitDataPartList
    suitDataPartList[part] = suitDataPartList[part] or {}
    id = checkNumber(id)
    local partData = suitDataPartList[part]
    for i, suitDataPartData in ipairs(partData) do
        local dataId = checkNumber(suitDataPartData.id)
        if dataId == id then
            table.remove(suitDataPartList[part], i)
            break
        end
    end
end

---UpdateSuitDataPartList
---@param newId number 背包中新增id
---@param oldId number 背包中要移除的id
---@param part number -1 核心, > 0 装备
function CardProgressionBaseEquipmentListNode:UpdateSuitDataPartList(newId, oldId, part)
    if newId > 0 then
        self:AddSuitDataPartListData(newId, part)
    end
    if oldId > 0 then
        self:RemoveSuitDataPartListData(oldId, part)
    end
end

function CardProgressionBaseEquipmentListNode:CheckIsCanInsert(partList, id, dojo, vo)
    local isCanInsert = true
    for i, v in ipairs(partList) do
        if checkNumber(v.id) == id then
            isCanInsert = false
            break
        end
    end
    if isCanInsert then
        isCanInsert = EquipUtils.CheckEquipFilterCondition({
            mainAttrId = dojo.mainAttrId,
            occupationId = checkNumber(vo.occupationId),
            playerCardId = dojo.playerCardId,
            quality = vo.quality or vo.rare
        }, self:GetGroups(), {career = self:GetCardCareerId()})
    end
    return isCanInsert
end

---RefreshScrollView
---@param result table
function CardProgressionBaseEquipmentListNode:RefreshScrollView(result)
    local count = #result
    local isShowList = count > 0
    if not isNull(self.EmptyNode) then
        KTool.SetActive(self.EmptyNode.gameObject, not isShowList)
    end
    KTool.SetActive(self.ScrollRoot.gameObject, isShowList)
    if isShowList then
        local List = self.ScrollView
        if not List.mLoopListView.IsListViewInit then
            List:InitListView(count, Bind(self, self.OnGetItemByIndex))
        else
            GameUtils.ReloadData(List, count)
            List:MovePanelToItemIndex(0)
        end
    else
        local part = self:GetPart()
        local config = {
            [-1] = localize("暂无装备核心"),
        }
        if self:GetFilterType() == FilTerType.SUIT then
            config[0] = localize("暂无该套装的装备")
        end

        local text = config[part]
        text = text ~= nil and text or localize("暂无装备")

        if not isNull(self.EmptyNode) then
            ---@type EmptyNodeMB
            local env = CfUtils.GetLuaScr(self.EmptyNode.gameObject, "Game.Behaviours.EmptyNodeMB")
            if not isNull(env) then
                env:SetText(text)
            end
        end
    end
    return isShowList
end

---OnGetItemByIndex
---@param idx number
function CardProgressionBaseEquipmentListNode:OnGetItemByIndex(cell, idx)
    if idx < 0 then return nil end

    ---@type UICultivateEquipBackpackCellNode
    local nodeEnv = CfUtils.GetLuaScr(cell, "Game.CardProgression.Equip.CardProgressionEquipmentListCell")
    if isNull(nodeEnv) then
        return nil
    end

    if nodeEnv.clickAction == nil then
        nodeEnv:SetClickCallback(Bind(self, self.OnClickCellAction))
        ---子类 方法
        if self.OnLongTapCellAction then
            nodeEnv:SetLongTapCallback(Bind(self, self.OnLongTapCellAction))
        end
    end

    local index     = idx + 1
    local cellTrans = cell.transform
    cellTrans.gameObject:EnsureComponent(IDType).id = index

    --- 调用子类
    self:RefreshGoodsNode(nodeEnv, index)

    return cell
end

