---切换装备页签
function CardProgressionBaseEquipmentListNode:SwitchSelectType(selectType)
    
    if self._selectedEquipmentType == SelectType.All then
        local text = self.TabGroup.transform:Find("All/Text")
        CfUtils.SetUISwitchText(text, 1)
    else
        local text = self.TabGroup.transform:Find(string.format('Mark1Filter%d/Text', self._selectedEquipmentType - 1))
        CfUtils.SetUISwitchImage(text, 1)
    end
    if selectType == SelectType.All then
        local text = self.TabGroup.transform:Find("All/Text")
        CfUtils.SetUISwitchText(text, 2)
    else
        local text = self.TabGroup.transform:Find(string.format('Mark1Filter%d/Text', selectType - 1))
        CfUtils.SetUISwitchImage(text, 2)
    end
    
    self._selectedEquipmentType = selectType

    --self:CloseFilter()
end

