---刷新装备数量
function CardProgressionBaseEquipmentListNode:RefreshEquipmentNum()
    local EquipCountText = self.TextEquipCount
    local backpackComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    local ownCount = backpackComp:GetGoodsNumByPacketId(Constants.BackpackTypeId.EQUIP)
    local backpackComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    local limitCount     = backpackComponent:GetPacketLimitByPacketId(Constants.BackpackTypeId.EQUIP)
    
    local text           = ownCount > limitCount and string.format("<color=#ff0000>%s</color>/%s", ownCount, limitCount) or string.format("%s/%s", ownCount, limitCount)
    CfUtils.FillText(EquipCountText, text)

    local TextTip        = self.TextTip
    if not isNull(TextTip) then
        KTool.SetActive(TextTip.gameObject, ownCount > limitCount)
    end
end

